use std::num::ParseIntError;

fn add_strings(a: &str, b: &str) -> Result<i32, ParseIntError> {
    let x: i32 = a.parse()?;
    let y: i32 = b.parse()?;
    Ok(x + y)
}

fn main() {
    println!("{:?}", add_strings("2", "3"));
    println!("{:?}", add_strings("2", "three"));
}

use std::num::ParseIntError;

fn main() -> Result<(), ParseIntError> {
    let n: i32 = "21".parse()?;
    println!("{}", n * 2);
    Ok(())
}

fn first_char_upper(s: &str) -> Option<char> {
    let c = s.chars().next()?;   // next() gives the first char, or None if s is empty
    Some(c.to_ascii_uppercase())
}

fn main() {
    println!("{:?}", first_char_upper("rust"));
    println!("{:?}", first_char_upper(""));
}

